:host{
  --bg:#f7f8fb; --card:#ffffff; --line:#e8e6e1; --text:#1f2328; --dim:#6b7280;
  /* 六档绿梯（亮色）：越用越多越深。按 OKLab 等距排的，相邻档 ΔE ≥0.08，13px 上也分得清 */
  --l0:#eceff1; --l1:#cdeab4; --l2:#a5dc8c; --l3:#6ec96a; --l4:#3fae52; --l5:#238b41; --l6:#14622f;
  --accent:#4d6bfe;
  /* 玻璃：卡片与浮层共用的乳白底 + 边框 */
  --glass:rgba(255,255,255,.58);
  --glass-strong:rgba(255,255,255,.76);
  --glass-line:rgba(255,255,255,.72);
  --glass-stroke:rgba(17,24,39,.07);
  --glass-shadow:0 6px 26px rgba(15,23,42,.09), 0 1px 3px rgba(15,23,42,.05);
}
/* 暗色变量抽成一份，两个入口共用：
     · 独立打开 → 跟随系统 prefers-color-scheme
     · 插件面板 → 靠 <html data-theme="dark"> 显式指定（DSH 的主题是应用内设置，
       不一定等于系统主题；早先只认媒体查询，就会出现「DSH 亮色、面板暗色」的错配） */
:host([data-theme="dark"]){
  --bg:#16181c; --card:#242629; --line:#34383d; --text:#e8eaed; --dim:#9aa0a6;
  /* 六档绿梯（暗色）：越用越多越亮，OKLab 等距，相邻档 ΔE ≥0.08 */
  --l0:#2d3134; --l1:#14512f; --l2:#1e6b3d; --l3:#2a8a4a; --l4:#3cb45c; --l5:#57d873; --l6:#8bf59a;
  --glass:rgba(38,41,46,.55); --glass-strong:rgba(44,47,53,.78);
  --glass-line:rgba(255,255,255,.08); --glass-stroke:rgba(255,255,255,.10);
  --glass-shadow:0 8px 30px rgba(0,0,0,.42), 0 1px 3px rgba(0,0,0,.3);
}
/* 没被显式指定主题时（独立打开），跟随系统 */
@media (prefers-color-scheme: dark){
  :host(:not([data-theme="light"])){
    --bg:#16181c; --card:#242629; --line:#34383d; --text:#e8eaed; --dim:#9aa0a6;
    --l0:#2d3134; --l1:#14512f; --l2:#1e6b3d; --l3:#2a8a4a; --l4:#3cb45c; --l5:#57d873; --l6:#8bf59a;
    --glass:rgba(38,41,46,.55); --glass-strong:rgba(44,47,53,.78);
    --glass-line:rgba(255,255,255,.08); --glass-stroke:rgba(255,255,255,.10);
    --glass-shadow:0 8px 30px rgba(0,0,0,.42), 0 1px 3px rgba(0,0,0,.3);
  }
}
*{box-sizing:border-box}
/* shadow 里没有 html/body：宿主元素自己就是面板的画布。
   ⚠️ 底色**不刷**（transparent）：面板现在活在宿主文档里，不刷底色就会直接透出设置窗口自己的材质
   —— 和「插件市场」那种原生分区一模一样，壁纸玻璃、窗口底色都自动对上。
   早先 iframe 版本不能透明，是因为 iframe 自有画布、默认是白的（白底 bug 的根源）；
   换成 shadow DOM 之后那个前提已经不成立，反而刷一层 --dsw-alias-bg-base 会在玻璃窗口里
   露出一块颜色不同的实心方块（2026-10-05 用户报的）。
   文字色仍然优先跟宿主（壁纸插件为了可读性会改写 --dsw-alias-label-primary）。 */
:host{display:block;background:transparent;
      color:var(--dsw-alias-label-primary,var(--text));
      font:14px/1.5 -apple-system,"Segoe UI","Microsoft YaHei",system-ui,sans-serif;}
/* 不支援 backdrop-filter 时退化成实色，别让文字失去对比 */
@supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))){
  .card,.modes,#tip{background:var(--card) !important}
}
.wrap{position:relative;z-index:1;max-width:1180px;margin:0 auto;padding:28px 22px 60px}
header{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap;margin-bottom:14px}
h1{font-size:19px;font-weight:650;margin:0}
.headRight{display:flex;align-items:center;gap:10px}
.sub{color:var(--dim);font-size:12.5px}
.sub b{color:var(--text);font-weight:600}
/* 视图切换 + 刷新 = 同一个胶囊：外框只有一层，靠分隔线分区 */
.modes{display:flex;align-items:center;gap:2px;padding:3px;
       background:var(--glass);border:1px solid var(--glass-line);border-radius:11px;
       backdrop-filter:blur(16px) saturate(165%);-webkit-backdrop-filter:blur(16px) saturate(165%);
       box-shadow:var(--glass-shadow)}
.modes button{border:0;background:transparent;color:var(--dim);font:inherit;font-size:13px;
              padding:5px 14px;border-radius:7px;cursor:pointer}
.modes button.on{background:var(--accent);color:#fff}
/* 只留图标的刷新键 */
.modes .refresh{display:inline-flex;align-items:center;justify-content:center;
                padding:5px 10px;margin-right:3px;color:var(--dim);
                border-right:1px solid var(--line);border-radius:7px 0 0 7px;
                transition:color .15s ease,background .15s ease,transform .12s ease}
.modes .refresh svg{display:block}
.modes .refresh:hover{color:var(--text);background:rgba(127,127,127,.08)}
.modes .refresh:active{transform:scale(.92)}
.modes .refresh[disabled]{opacity:.6;cursor:default}
.modes .refresh.busy svg{animation:spin .8s linear infinite}
@keyframes spin{to{transform:rotate(360deg)}}
@keyframes errPulse{0%,100%{transform:translateX(0)}25%{transform:translateX(-2px)}75%{transform:translateX(2px)}}
.modes .refresh.err{color:#d92d20;animation:errPulse .32s ease 2}
.card{background:var(--glass);border:1px solid var(--glass-line);border-radius:16px;
      padding:18px 18px 14px;margin-top:16px;
      backdrop-filter:blur(20px) saturate(170%);-webkit-backdrop-filter:blur(20px) saturate(170%);
      box-shadow:var(--glass-shadow)}
.stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:14px}
.stat .k{color:var(--dim);font-size:12px}
.stat .v{font-size:22px;font-weight:660;letter-spacing:-.4px;margin-top:2px}
.stat .v small{font-size:13px;font-weight:500;color:var(--dim);margin-left:3px}
.gridbox{overflow-x:auto;overflow-y:hidden;
         /* 内边距不是装饰：悬停会把格子放大到 1.55×、再描一圈 1.5px 的环，
            整个绘制范围比原格子外扩约 5.9px；而滚动容器的裁剪边就是它自己的 padding box。
            不留这点余量，最下面一行的放大环会被横向滚动条那一条切掉（2026-10-04 用户报的
            「格子边框边缘被裁」）。横向也留 6px，拉到最右时最后一列同样不被切。 */
         padding:0 6px 8px 0;
         /* 滚动条：轨道必须透明。UA 默认用系统 Canvas 色画轨道（暗色下纯黑、亮色下纯白），
            面板背景在壁纸模式下是透明的，于是这条固定底色会横在热力图下面很扎眼。
            滑块用中性半透明灰，压在深底/浅底/壁纸上都看得见、也不抢戏。 */
         scrollbar-width:thin;scrollbar-color:rgba(127,127,127,.55) transparent}
.gridbox::-webkit-scrollbar{height:10px;width:10px}
.gridbox::-webkit-scrollbar-track,
.gridbox::-webkit-scrollbar-corner{background:transparent}
.gridbox::-webkit-scrollbar-thumb{background:rgba(127,127,127,.5);border-radius:6px}
.gridbox::-webkit-scrollbar-thumb:hover{background:rgba(127,127,127,.72)}
/* 月份轴：绝对定位，每个标签的 left = 列索引 × 17px（13 格子 + 4 间隙），
   和格子的几何完全一致。以前是一排 span（宽 14px、有文字的改 auto）+ gap:4px，
   每个单元 18px 而格子是 17px，53 列累计漂 53px，到 9 月能偏出 5 个格子。 */
.months{position:relative;height:14px;margin:0 0 5px 27px}
.months span{position:absolute;top:0;font-size:11px;color:var(--dim);white-space:nowrap}
.gridrow{display:flex;align-items:flex-start}
.wd{display:flex;flex-direction:column;gap:4px;width:27px;flex:0 0 27px}
.wd span{height:13px;font-size:10px;color:var(--dim);line-height:13px}
.cols{display:flex;gap:4px}
.col{display:flex;flex-direction:column;gap:4px}
.c{width:13px;height:13px;border-radius:3px;background:var(--l0)}
.c[data-tip]{cursor:pointer}
/* 六档：只有 l1..l6。以前这里有 l1..l4 + 一条 "l5 兜底成 l4" —— 档数一改就把 l5 压掉了，
   所以那条兜底已经删掉：现在 level() 恰好返回 0..6，越界不再可能（顶格返回 LV.length = 6）。 */
.c.l1{background:var(--l1)} .c.l2{background:var(--l2)} .c.l3{background:var(--l3)}
.c.l4{background:var(--l4)} .c.l5{background:var(--l5)} .c.l6{background:var(--l6)}
/* 图例已按用户要求撤掉（"神秘一点"）：档位含义只靠悬停看。
   ⚠️ 但 .legend 的样式先留着 —— 运行时装资产那条路只换 CSS 不换 HTML，
   正在跑的旧客户端手里还有那份带图例的旧结构，样式删了它会散成一排裸色块。
   下一次重启后这份 HTML 就没人用了，届时可以连同这两条规则一起删。 */
.legend{display:flex;align-items:center;gap:5px;justify-content:flex-end;color:var(--dim);font-size:11.5px;margin-top:10px}
.legend i{width:13px;height:13px;border-radius:3px;display:inline-block}
/* 热力图卡片：图例没了，底部留白跟着收上来（原来 14px 是给图例垫的），
   现在上下都是 18px（10px 卡片内边距 + 8px 网格容器内边距），视觉对称 */
.gridcard{padding-bottom:10px}
table{width:100%;border-collapse:collapse;font-size:13px}
th,td{text-align:left;padding:7px 8px;border-bottom:1px solid var(--line);white-space:nowrap}
/* 第一列是名字（API Key / 模型），长名字允许换行——数字列保持不换行对齐 */
th:first-child,td:first-child{white-space:normal;overflow-wrap:anywhere}
th{color:var(--dim);font-weight:500;font-size:12px}
td.num,th.num{text-align:right;font-variant-numeric:tabular-nums}
.bar{height:7px;border-radius:4px;background:var(--accent);opacity:.75;display:inline-block;vertical-align:middle}
.two{display:grid;grid-template-columns:1fr;gap:16px}
.two>*{min-width:0}          /* 允许子项收缩，别再顶破容器 */
/* 两张拆分表**一律上下排**（先「按 API Key」，再「按模型」）。
   早先写的是 @media(min-width:900px) 时并排两列 —— 那个 900px 判的是**视口宽度**，
   而面板在 DSH 设置页里被塞进内容列（列宽比视口窄得多，七八百像素），媒体查询照样命中，
   于是两张表并排、右边那张被容器裁掉（2026-10-04 用户报的）。
   表格单元格是 white-space:nowrap，并排所需的最小宽度远大于内容列 ⇒ 只能上下排。
   （将来若真想在宽屏并排，正确做法是容器查询 @container，而不是媒体查询。） */
h2{font-size:14px;font-weight:600;margin:0 0 10px}
/* 悬浮提示：换成乳白玻璃（原来是一块纯黑） */
#tip{position:fixed;z-index:99;pointer-events:none;font-size:12px;
     /* popover 进 top layer 时 UA 会塞进 inset:0 + margin:auto，得清掉 */
     inset:auto;margin:0;
     padding:9px 12px;border-radius:12px;opacity:0;transition:opacity .1s;max-width:300px;line-height:1.55;
     background:var(--glass-strong);color:var(--text);
     border:1px solid var(--glass-line);
     backdrop-filter:blur(22px) saturate(180%);-webkit-backdrop-filter:blur(22px) saturate(180%);
     box-shadow:0 12px 34px rgba(15,23,42,.16), 0 2px 8px rgba(15,23,42,.08)}
#tip b{font-weight:650}
#tip.on{opacity:1}
.note{color:var(--dim);font-size:12px;margin-top:12px}
.note code{background:rgba(127,127,127,.14);padding:1px 5px;border-radius:4px}

/* ---------- 动效（对标 Codex：草地逐列生长 + 数字滚动） ---------- */
@keyframes cellIn{
  0%  {transform:scale(.35) translateY(3px);opacity:0;filter:brightness(1.7)}
  55% {transform:scale(1.1)  translateY(0);  opacity:1;filter:brightness(1.22)}
  100%{transform:scale(1)    translateY(0);  opacity:1;filter:brightness(1)}
}
.cols.animate .c{animation:cellIn .46s cubic-bezier(.22,.72,.28,1.02) both}
.cols.animate .col:nth-child(1) .c{animation-delay:0s}
.cols.animate .col:nth-child(2) .c{animation-delay:.022s}
