.cols.animate .col:nth-child(21) .c{animation-delay:.44s}
.cols.animate .col:nth-child(22) .c{animation-delay:.462s}
.cols.animate .col:nth-child(23) .c{animation-delay:.484s}
.cols.animate .col:nth-child(24) .c{animation-delay:.506s}
.cols.animate .col:nth-child(25) .c{animation-delay:.528s}
.cols.animate .col:nth-child(26) .c{animation-delay:.55s}
.cols.animate .col:nth-child(27) .c{animation-delay:.572s}
.cols.animate .col:nth-child(28) .c{animation-delay:.594s}
.cols.animate .col:nth-child(29) .c{animation-delay:.616s}
.cols.animate .col:nth-child(30) .c{animation-delay:.638s}
.cols.animate .col:nth-child(31) .c{animation-delay:.66s}
