.cols.animate .col:nth-child(52) .c{animation-delay:1.122s}
.cols.animate .col:nth-child(53) .c{animation-delay:1.144s}

.c{transition:transform .12s ease,box-shadow .12s ease}
.c:hover{transform:scale(1.55);box-shadow:0 0 0 1.5px var(--card),0 1px 5px rgba(0,0,0,.18);position:relative;z-index:3}
.c:active{transform:scale(1.25)}

@keyframes statIn{from{opacity:0;transform:translateY(7px)}to{opacity:1;transform:none}}
.stat{animation:statIn .42s ease both}
.stat:nth-child(1){animation-delay:.02s} .stat:nth-child(2){animation-delay:.06s}
.stat:nth-child(3){animation-delay:.1s}  .stat:nth-child(4){animation-delay:.14s}
.stat:nth-child(5){animation-delay:.18s} .stat:nth-child(6){animation-delay:.22s}
.stat .v{font-variant-numeric:tabular-nums}

@keyframes rowIn{from{opacity:0;transform:translateX(-7px)}to{opacity:1;transform:none}}
tbody tr{animation:rowIn .38s ease both}
tbody tr:nth-child(1){animation-delay:.04s} tbody tr:nth-child(2){animation-delay:.09s}
tbody tr:nth-child(3){animation-delay:.14s} tbody tr:nth-child(4){animation-delay:.19s}
tbody tr:nth-child(5){animation-delay:.24s} tbody tr:nth-child(6){animation-delay:.29s}
tbody tr:nth-child(7){animation-delay:.34s} tbody tr:nth-child(8){animation-delay:.39s}
.bar{transform-origin:left center;animation:barIn .75s cubic-bezier(.2,.8,.25,1) both}
@keyframes barIn{from{transform:scaleX(0);opacity:.25}to{transform:scaleX(1);opacity:.75}}

.modes button{transition:background .18s ease,color .18s ease,transform .12s ease}
.modes button.on{animation:pill .28s ease}
@keyframes pill{0%{transform:scale(.93)}60%{transform:scale(1.035)}100%{transform:scale(1)}}
@keyframes tipIn{from{opacity:0;transform:translateY(4px) scale(.97)}to{opacity:.96;transform:none}}
#tip.on{opacity:.96;animation:tipIn .13s ease}
.card{transition:box-shadow .2s ease}

@media (prefers-reduced-motion: reduce){
  .cols.animate .c,.stat,tbody tr,.bar,#tip.on,.modes button.on{animation:none !important}
  .c:hover{transform:none}
}

/* 内嵌（shadow）模式：宽度交给宿主容器 */
.wrap{max-width:none;padding:2px 2px 10px}
/* 壁纸插件在跑时（客户端把 body[data-we-wallpaper] 镜像到宿主元素上）：
   卡片 / 胶囊 / 浮层改用宿主那套玻璃面 —— --dsw-alias-bg-layer-* 在壁纸激活时
   就是「主题底色压可读性下限 + 玻璃色按玻璃透明度混合」的配方，
   于是面板与设置窗口里其它玻璃同一配方，壁纸也从面板底下透出来。 */
:host([data-we]) .card,
:host([data-we]) .modes,
:host([data-we]) #tip{background:var(--dsw-alias-bg-layer-1,var(--glass))}
:host([data-we]){--text:var(--dsw-alias-label-primary,var(--text));--dim:var(--dsw-alias-label-secondary,var(--dim));--line:var(--dsw-alias-border-l1,var(--line))}
